519		if len(res.Series) != 1 {
520			t.Fatalf("series = %+v", res.Series)
521		}
522		avg := res.Series[0].Average
523		if math.IsInf(avg, 0) || math.IsNaN(avg) {
524			t.Fatalf("average must be finite, got %v", avg)
525		}
526		if avg != 1e308 {
527			t.Fatalf("average = %v, want 1e308", avg)
528		}
529	
530		// 反号极值相减（朴素求和与朴素增量都会溢出）也要给出有限结果。
531		store2 := NewMetricStore()
532		mustOK(t, store2, `[
533			{"name":"m","timestamp":1,"value":1e308},
534			{"name":"m","timestamp":2,"value":-1e308}
535		]`)
536		res = mustQuery(t, store2, `{"op":"query","name":"m","start":0,"end":100}`)
537		avg = res.Series[0].Average
538		if math.IsInf(avg, 0) || math.IsNaN(avg) {
539			t.Fatalf("average of opposite extremes must be finite, got %v", avg)
540		}
541	
542		// 结果与写入顺序无关：反序写入同一点集应得到相同均值。
543		store3 := NewMetricStore()
544		mustOK(t, store3, `[
545			{"name":"m","timestamp":2,"value":-1e308},
546			{"name":"m","timestamp":1,"value":1e308}
547		]`)
548		res3 := mustQuery(t, store3, `{"op":"query","name":"m","start":0,"end":100}`)
549		if res3.Series[0].Average != avg {
550			t.Fatalf("average depends on write order: %v vs %v", res3.Series[0].Average, avg)
551		}
552	}
